import{_ as i,o as r,c as l,a as p}from"./app.4152ce04.js";const t={},n=p('<h1 id="\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u1105\u1161\u1102\u1173\u11AB-\u1109\u1175\u1109\u1173\u1110\u1166\u11B7\u110B\u1173\u11AF-\u110B\u1175\u1112\u1162\u1112\u1161\u1102\u1173\u11AB-\u110B\u1175\u11AF" tabindex="-1"><a class="header-anchor" href="#\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u1105\u1161\u1102\u1173\u11AB-\u1109\u1175\u1109\u1173\u1110\u1166\u11B7\u110B\u1173\u11AF-\u110B\u1175\u1112\u1162\u1112\u1161\u1102\u1173\u11AB-\u110B\u1175\u11AF" aria-hidden="true">#</a> \uC0AC\uB78C\uC774\uB77C\uB294 \uC2DC\uC2A4\uD15C\uC744 \uC774\uD574\uD558\uB294 \uC77C</h1><p>\uB098\uB294 \uC131\uC778\uC774 \uB41C \uD6C4 \uD604 \uD68C\uC0AC\uC5D0 \uC785\uC0AC\uD558\uAE30 \uC9C1\uC804\uAE4C\uC9C0 \uD56D\uC0C1 \uAD50\uC721 \uD65C\uB3D9\uC744 \uD574\uC654\uACE0, \uC120\uBC30\uB2D8, \uC120\uC0DD\uB2D8, \uBA58\uD1A0\uB2D8, \uCF54\uCE58\uB2D8, \uAC15\uC0AC\uB2D8 \uB4F1 \uC5EC\uB7EC \uD638\uCE6D\uC73C\uB85C \uBD88\uB838\uC5C8\uB2E4.</p><p>\uB098\uB294 \uD559\uC2B5\uBCF4\uB2E4 \uAD50\uC721\uC744 \uC88B\uC544\uD588\uACE0, \uC9C1\uBB34\uC131\uD5A5 \uD14C\uC2A4\uD2B8\uB97C \uD558\uBA74 \uD56D\uC0C1 \uC5D4\uC9C0\uB2C8\uC5B4\uBCF4\uB2E4 \uAD50\uC721\uC790\uAC00 \uB354 \uC801\uD569\uD558\uB2E4\uB294 \uACB0\uACFC\uB97C \uC5BB\uC5C8\uB2E4. \uADF8\uB798\uC11C \uC2A4\uC2A4\uB85C \uAC00\uB974\uCE58\uB294 \uAC83\uC5D0 \uC7AC\uB2A5\uC774 \uC788\uB2E4\uACE0 \uC0DD\uAC01\uD588\uB2E4.</p><p>\uADF8\uB7F0\uB370 \uAC00\uB974\uCE58\uB294 \uAC83\uACFC \uAC00\uB974\uCE58\uB294 \uAC83\uC744 \uC88B\uC544\uD558\uB294 \uAC83\uC740 \uB2E4\uB974\uB2E4.</p><p>\uAC1C\uBC1C\uC744 \uC88B\uC544\uD558\uB294 \uAC83\uACFC \uAC1C\uBC1C\uC744 \uC798\uD558\uB294 \uAC8C \uB2E4\uB978 \uAC83\uCC98\uB7FC. \uC77C\uC744 \uC88B\uC544\uD558\uB294 \uAC83\uACFC \uC77C\uC744 \uC798\uD558\uB294 \uAC8C \uB2E4\uB978 \uAC83\uCC98\uB7FC.</p><p>\uBB3C\uB860 \uB300\uBD80\uBD84 \uC88B\uC544\uD558\uBA74 \uC798\uD558\uAE30\uB3C4 \uD55C\uB2E4. \uADF8\uB9CC\uD07C \uC2DC\uAC04\uC744 \uB9CE\uC774 \uD22C\uC790\uD574\uC11C \uADF8\uB7F0 \uAC8C \uC544\uB2D0\uAE4C?</p><p>\uADF8\uB807\uB2E4\uBA74 \uB098\uB294 \uAD50\uC721\uC744 \uC88B\uC544\uD558\uB294 \uC0AC\uB78C\uC77C\uAE4C, \uAD50\uC721\uC744 \uC798\uD558\uB294 \uC0AC\uB78C\uC77C\uAE4C?</p><p>\uC0DD\uAC01\uD574\uBCF4\uBA74 \uC798 \uBAA8\uB974\uACA0\uB2E4.</p><h2 id="\u1102\u1161\u1102\u1173\u11AB-\u110C\u1175\u1109\u1175\u11A8\u110B\u1173\u11AF-\u110C\u1161\u11AF-\u110C\u1165\u11AB\u1103\u1161\u11AF\u1112\u1161\u1102\u1173\u11AB-\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u11AB\u1100\u1161" tabindex="-1"><a class="header-anchor" href="#\u1102\u1161\u1102\u1173\u11AB-\u110C\u1175\u1109\u1175\u11A8\u110B\u1173\u11AF-\u110C\u1161\u11AF-\u110C\u1165\u11AB\u1103\u1161\u11AF\u1112\u1161\u1102\u1173\u11AB-\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u11AB\u1100\u1161" aria-hidden="true">#</a> \uB098\uB294 \uC9C0\uC2DD\uC744 \uC798 \uC804\uB2EC\uD558\uB294 \uC0AC\uB78C\uC778\uAC00?</h2><p>\uAD50\uC721 \uD65C\uB3D9\uC744 \uD558\uB2E4 \uBCF4\uBA74 \uC0AC\uB78C\uB9C8\uB2E4 \uC9C0\uC2DD\uC744 \uC804\uB2EC\uD558\uB294 \uBC29\uBC95\uC774 \uBB34\uCC99 \uB2E4\uC591\uD558\uACE0, \uAC01\uAC01\uC758 \uBC29\uBC95\uC5D0 \uB530\uB77C \uAD50\uC721\uC744 \uBC1B\uB294 \uC0AC\uB78C\uC774 \uC9C0\uC2DD\uC744 \uBC1B\uC544\uB4E4\uC774\uB294 \uAE4A\uC774\uB3C4 \uB2EC\uB77C\uC9C4\uB2E4\uB294 \uAC78 \uC54C\uAC8C \uB41C\uB2E4.</p><p>\uADF8\uB9AC\uACE0 \uACB0\uAD6D \uB0B4\uAC00 \uD558\uACE0 \uC2F6\uC740 \uC774\uC57C\uAE30\uB294,</p><p><strong>\u201C\uB098\uB294 \uC9C0\uC2DD\uC744 \uC798 \uC804\uB2EC\uD558\uC9C0 \uBABB\uD558\uB294 \uC0AC\uB78C\uC77C \uC218\uB3C4 \uC788\uB2E4.\u201D</strong></p><p>\uAD50\uC721\uC5D0 \uB300\uD55C \uACBD\uD5D8\uC774 \uB9CE\uC740 \uAC83\uACFC \uAD50\uC721\uC744 \uC798\uD558\uB294 \uAC83\uC740 \uB2E4\uB974\uB2E4.</p><p>\uADF8\uB807\uC9C0\uB9CC \uB098\uB294 \u201C\uD6C8\uB828\u201D\uC740 \uC798 \uC2DC\uD0A4\uB294 \uD3B8\uC774\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</p><p>\uADFC\uB370 \uC774\uAC83\uB3C4 \uCC29\uAC01\uC77C \uC218 \uC788\uB2E4.</p><p>\uC560\uCD08\uC5D0 \uC7AC\uB2A5 \uC788\uB294 \uC0AC\uB78C\uB4E4\uC744 \uAC00\uB974\uCCE4\uAE30 \uB54C\uBB38\uC5D0 \u201C\uB098 \uCACC \uD558\uB124?\u201D\uB77C\uACE0 \uC0DD\uAC01\uD588\uB358 \uAC74 \uC544\uB2D0\uAE4C? \uC778\uD48B\uC744 \uB123\uC73C\uBA74 \uC544\uC6C3\uD48B\uC774 \uB098\uC62C \uC218 \uC788\uB294 \uC0AC\uB78C\uB4E4\uC744 \uB0B4\uAC00 \uAC00\uB974\uCCE4\uAE30 \uB54C\uBB38\uC774\uC9C0 \uC54A\uC744\uAE4C?</p><p>\uADF8\uB798\uC11C \uC798 \uBAA8\uB974\uACA0\uB2E4.</p><h2 id="\u1102\u1161\u1102\u1173\u11AB-\u110B\u1165\u1104\u1165\u11AB-\u1107\u1161\u11BC\u1109\u1175\u11A8\u110B\u1173\u1105\u1169-\u1109\u1161\u1105\u1161\u11B7\u110B\u1173\u11AF-\u1100\u1161\u1105\u1173\u110E\u1167\u110B\u116A\u11BB\u110B\u1173\u11AF\u1101\u1161" tabindex="-1"><a class="header-anchor" href="#\u1102\u1161\u1102\u1173\u11AB-\u110B\u1165\u1104\u1165\u11AB-\u1107\u1161\u11BC\u1109\u1175\u11A8\u110B\u1173\u1105\u1169-\u1109\u1161\u1105\u1161\u11B7\u110B\u1173\u11AF-\u1100\u1161\u1105\u1173\u110E\u1167\u110B\u116A\u11BB\u110B\u1173\u11AF\u1101\u1161" aria-hidden="true">#</a> \uB098\uB294 \uC5B4\uB5A4 \uBC29\uC2DD\uC73C\uB85C \uC0AC\uB78C\uC744 \uAC00\uB974\uCCD0\uC654\uC744\uAE4C?</h2><p>\uBB38\uB4DD \uAD50\uC721\uC790\uB97C \uBD80\uB974\uB294 \uAC01\uAC01\uC758 \uD638\uCE6D\uC5D0 \uB300\uD55C \uC815\uC758\uAC00 \uAD81\uAE08\uD574\uC11C GPT\uC5D0\uAC8C \uBB3C\uC5B4\uBD24\uB2E4.</p><p>\uAD50\uC721\uC790\uB97C \uB2E8\uC21C\uD788 <strong>\uC9C0\uC2DD\uC744 \uC804\uB2EC\uD558\uB294 \uC0AC\uB78C</strong>\uC774 \uC544\uB2C8\uB77C \uC0C1\uB300\uC758 \uC131\uC7A5\uC5D0 \uAC1C\uC785\uD558\uB294 \uC5ED\uD560\uB85C \uBCF4\uBA74 \uAF64 \uB2E4\uC591\uD558\uAC8C \uB098\uB20C \uC218 \uC788\uB2E4\uACE0 \uD55C\uB2E4.</p><ul><li><strong>Teacher / Instructor \u2014 \uAD50\uC0AC\xB7\uAC15\uC0AC</strong>: \uC9C0\uC2DD\uACFC \uAE30\uC220\uC744 \uC9C1\uC811 \uAC00\uB974\uCE58\uB294 \uC0AC\uB78C</li><li><strong>Tutor \u2014 \uD29C\uD130</strong>: \uAC1C\uC778\uC758 \uC218\uC900\uC5D0 \uB9DE\uCDB0 \uBD80\uC871\uD55C \uBD80\uBD84\uC744 \uBCF4\uC644\uD574\uC8FC\uB294 \uC0AC\uB78C</li><li><strong>Mentor \u2014 \uBA58\uD1A0</strong>: \uC790\uC2E0\uC758 \uACBD\uD5D8\uACFC \uAD00\uC810\uC744 \uBC14\uD0D5\uC73C\uB85C \uBC29\uD5A5\uACFC \uC870\uC5B8\uC744 \uC8FC\uB294 \uC0AC\uB78C</li><li><strong>Coach \u2014 \uCF54\uCE58</strong>: \uB2F5\uC744 \uC9C1\uC811 \uC8FC\uAE30\uBCF4\uB2E4 \uC9C8\uBB38\uACFC \uD53C\uB4DC\uBC31\uC73C\uB85C \uC2A4\uC2A4\uB85C \uC131\uC7A5\uD558\uAC8C \uB9CC\uB4DC\uB294 \uC0AC\uB78C</li><li><strong>Facilitator \u2014 \uD37C\uC2E4\uB9AC\uD14C\uC774\uD130</strong>: \uD559\uC2B5\uC774\uB098 \uD1A0\uB860\uC774 \uC798 \uC77C\uC5B4\uB098\uB3C4\uB85D \uD658\uACBD\uACFC \uACFC\uC815\uC744 \uC124\uACC4\uD558\uB294 \uC0AC\uB78C</li><li><strong>Trainer \u2014 \uD2B8\uB808\uC774\uB108</strong>: \uBC18\uBCF5\uC801\uC778 \uD6C8\uB828\uC744 \uD1B5\uD574 \uD2B9\uC815 \uB2A5\uB825\uC744 \uC219\uB828\uC2DC\uD0A4\uB294 \uC0AC\uB78C</li><li><strong>Role Model \u2014 \uB864\uBAA8\uB378</strong>: \uD589\uB3D9\uACFC \uD0DC\uB3C4 \uC790\uCCB4\uB85C \uD559\uC2B5\uC758 \uAE30\uC900\uC744 \uBCF4\uC5EC\uC8FC\uB294 \uC0AC\uB78C</li></ul><p>\uC9C0\uB09C\uB0A0\uC744 \uC0DD\uAC01\uD574\uBCF4\uBA74 \uC758\uB3C4\uCE58 \uC54A\uAC8C \uC774 \uAC01\uAC01\uC758 \uB2E8\uACC4\uB97C \uBC1F\uC544\uC654\uB358 \uAC83 \uAC19\uB2E4. \uC5B4\uCA4C\uBA74 \uC790\uC5F0\uC2A4\uB7EC\uC6B4 \uACFC\uC815\uC77C \uC218\uB3C4 \uC788\uACA0\uC9C0?</p><ul><li>\uC77C\uB2E8 \uC9C0\uC2DD\uC744 \uC804\uB2EC\uD574\uBCF4\uACE0 <strong>(\uD2F0\uCE6D)</strong></li><li>\uC131\uC7A5\uC758 \uBC29\uD5A5\uC744 \uC54C\uB824\uC8FC\uACE0 <strong>(\uBA58\uD1A0\uB9C1)</strong></li><li>\uC131\uC7A5\uD560 \uC218 \uC788\uB3C4\uB85D \uC9C1\uC811\uC801\uC778 \uB3C4\uC6C0\uC774\uB098 \uC870\uC5B8\uC744 \uC8FC\uACE0 <strong>(\uCF54\uCE6D)</strong></li><li>\uAD50\uC721\uC744 \uD560 \uC218 \uC788\uB294 \uD658\uACBD\uC774\uB098 \uC7A5\uCE58\uC5D0 \uB300\uD574 \uACE0\uBBFC\uD558\uACE0 \uAD6C\uC131\uD574\uC8FC\uACE0 <strong>(\uD37C\uC2E4\uB9AC\uD14C\uC774\uD305)</strong></li><li>\uBC18\uBCF5 \uD6C8\uB828\uC744 \uC2DC\uCF1C\uC8FC\uAE30\uB3C4 \uD558\uACE0. <strong>(\uD2B8\uB808\uC774\uB2DD)</strong><ul><li>\u201C\uC798\uD588\uC5B4. \uB2E4\uC2DC \uD574\uBCF4\uC790.\u201D</li><li>\u201C\uC774\uBC88\uC5D0\uB294 \uB354 \uBE60\uB974\uAC8C \uD574\uBCF4\uC790.\u201D</li></ul></li><li>\uBD80\uB044\uB7FD\uC9C0\uB9CC \uB204\uAD70\uAC00\uC5D0\uAC8C <strong>\uB864\uBAA8\uB378</strong>\uC774 \uB418\uAE30\uB3C4 \uD558\uACE0</li></ul><p>\uC774\uAC78 \uAD50\uC721\uC758 \uC804\uCCB4 \uC2DC\uC2A4\uD15C\uC774\uB77C\uACE0 \uC0DD\uAC01\uD558\uBA74, \uB098\uB294 \uAD50\uC721\uC744 \uD558\uBA74\uC11C <strong>\uC810\uC810 \uC5ED\uD560\uC744 \uD655\uC7A5</strong>\uD588\uB358 \uAC83 \uAC19\uAE30\uB3C4 \uD558\uB2E4.</p><p>\uCC98\uC74C\uC5D0\uB294 \uB0B4\uAC00 \uC54C\uACE0 \uC788\uB294 \uAC83\uC744 \uC804\uB2EC\uD558\uB294 \uC0AC\uB78C\uC774\uC5C8\uB2E4\uBA74, \uC810\uC810 \uADF8 \uC0AC\uB78C\uC774 <strong>\uC131\uC7A5\uD558\uB294 \uACFC\uC815 \uC790\uCCB4\uC5D0 \uAC1C\uC785\uD558\uB294 \uC0AC\uB78C</strong>\uC774 \uB418\uC5B4\uAC04 \uAC83\uC774\uB2E4.</p><h2 id="\u1100\u1173\u1105\u1165\u11AB\u1103\u1166-\u1109\u1161\u1105\u1161\u11B7\u1106\u1161\u1103\u1161-\u1102\u1165\u1106\u116E-\u1103\u1161\u1105\u1173\u1103\u1161" tabindex="-1"><a class="header-anchor" href="#\u1100\u1173\u1105\u1165\u11AB\u1103\u1166-\u1109\u1161\u1105\u1161\u11B7\u1106\u1161\u1103\u1161-\u1102\u1165\u1106\u116E-\u1103\u1161\u1105\u1173\u1103\u1161" aria-hidden="true">#</a> \uADF8\uB7F0\uB370 \uC0AC\uB78C\uB9C8\uB2E4 \uB108\uBB34 \uB2E4\uB974\uB2E4</h2><p>\uADF8\uB798\uC11C \uAC1C\uBC1C\uB3C4 \uADF8\uB807\uC9C0\uB9CC, \uAD50\uC721\uB3C4 \uAE4A\uC774 \uC788\uAC8C \uC0DD\uAC01\uD574\uBCF4\uBA74 \uCC38 \uC5B4\uB824\uC6B4 \uC601\uC5ED\uC774\uB2E4.</p><p>\uC9C0\uC2DD\uC758 \uBC1C\uC0B0\uB3C4 \uBB34\uCC99 \uC911\uC694\uD558\uC9C0\uB9CC, \uC9C0\uC2DD\uC744 \uC218\uC2E0\uD558\uB294 \uC0AC\uB78C\uC758 \uC0C1\uD0DC\uB3C4 \uACE0\uB824\uD574\uC57C \uD55C\uB2E4.</p><p>\uC0AC\uB78C\uB9C8\uB2E4 \uC131\uD5A5\uC774 \uB2E4\uB974\uAE30 \uB54C\uBB38\uC5D0 \uD589\uB3D9\uC744 \uD2B8\uB9AC\uAC70\uD558\uACE0 \uC9C0\uC18D\uC2DC\uD0A4\uAE30 \uC704\uD55C \uC778\uD48B\uC758 \uD615\uD0DC\uB098 \uBC29\uD5A5\uB3C4 \uAC01\uAE30 \uB2E4\uB974\uB2E4.</p><p>\uAC8C\uB2E4\uAC00 \uBD88\uD2B9\uC815 \uB2E4\uC218\uAC00 \uB300\uC0C1\uC774\uB77C\uBA74 \uB354 \uC5B4\uB835\uB2E4.</p><p>\uC655\uCD08\uBCF4\uB97C \uB300\uC0C1\uC73C\uB85C \uD560 \uC218\uB3C4 \uC788\uACE0, \uCD08\uBCF4\uB098 \uC911\uC218 \uD639\uC740 \uB2A5\uC219\uD55C \uC219\uB828\uC790\uAC00 \uC9C0\uC2DD \uC804\uB2EC\uC758 \uB300\uC0C1\uC77C \uC218\uB3C4 \uC788\uB2E4.</p><p>\uADF8\uB9AC\uACE0 \uC0AC\uB78C\uC740 \uC815\uB9D0 \uC81C\uAC01\uAC01\uC774\uB2E4.</p><ul><li>\uB204\uAD70\uAC00\uB294 \uAC1C\uB5A1\uAC19\uC774 \uB9D0\uD574\uB3C4 \uCC30\uB5A1\uAC19\uC774 \uC54C\uC544\uB4E3\uACE0, \uB204\uAD70\uAC00\uB294 \uCC30\uB5A1\uAC19\uC774 \uB9D0\uD574\uB3C4 \uAC1C\uB5A1\uAC19\uC774 \uC54C\uC544\uB4E3\uB294\uB2E4.</li><li>\uB204\uAD70\uAC00\uB294 \uC774\uD574\uD558\uC9C0 \uC54A\uC544\uB3C4 \uC2E4\uD589\uD560 \uC218 \uC788\uACE0, \uB204\uAD70\uAC00\uB294 \uC774\uD574\uB97C \uD574\uC57C \uC2E4\uD589\uD560 \uC218 \uC788\uB2E4.</li><li>\uB204\uAD70\uAC00\uB294 \uACC4\uD68D\uC774 \uD544\uC694\uD558\uACE0, \uB204\uAD70\uAC00\uB294 \uC2E4\uD589\uC774 \uD544\uC694\uD558\uB2E4. <ul><li>\uC2E4\uD589\uC774 \uC6B0\uC120\uB418\uB2E4 \uBCF4\uBA74 \uC5C9\uB6B1\uD55C \uBC29\uD5A5\uC73C\uB85C \uD758\uB7EC\uAC00\uACE0 \uB3C8\uC774\uB098 \uC2DC\uAC04 \uB4F1 \uBD88\uD544\uC694\uD55C \uBE44\uC6A9\uC744 \uC0AC\uC6A9\uD558\uAC8C \uB41C\uB2E4.</li><li>\uACC4\uD68D\uC774 \uC6B0\uC120\uB418\uB2E4 \uBCF4\uBA74 \uD53C\uB4DC\uBC31\uC774 \uB2A6\uC5B4\uC9C0\uACE0, \uC544\uC608 \uC2E4\uD589\uC744 \uBABB \uD558\uB294 \uC0C1\uD0DC\uAC00 \uB418\uAE30\uB3C4 \uD55C\uB2E4.</li></ul></li><li>\uB204\uAD70\uAC00\uB294 \uC790\uC874\uC2EC\uC744 \uAC74\uB4DC\uB824\uC57C \uD558\uACE0, \uB204\uAD70\uAC00\uB294 \uACF5\uAC10\uC774 \uD544\uC694\uD558\uB2E4.</li><li>\uB204\uAD70\uAC00\uB294 \uC218\uB3D9\uC801\uC774\uACE0, \uB204\uAD70\uAC00\uB294 \uB2A5\uB3D9\uC801\uC774\uB2E4. <ul><li>\uC218\uB3D9\uC801\uC774\uB77C\uBA74 \uB300\uCCB4\uB85C \uC2DC\uD0A4\uB294 \uAC74 \uC5B4\uB5BB\uAC8C\uB4E0 \uD55C\uB2E4.</li><li>\uB2A5\uB3D9\uC801\uC774\uB77C\uBA74 \uB300\uCCB4\uB85C \uD558\uACE0 \uC2F6\uC5B4\uC57C \uD55C\uB2E4.</li></ul></li></ul><p>\uADF8\uB798\uC11C \uCC38 \uB9CE\uC740 \uAC83\uB4E4\uC774 \uC0C1\uCDA9\uD55C\uB2E4.</p><p>\uB204\uAD70\uAC00\uC5D0\uAC8C \uD6A8\uACFC\uC801\uC774\uC5C8\uB358 \uAD50\uC721 \uBC29\uBC95\uC774 \uB2E4\uB978 \uC0AC\uB78C\uC5D0\uAC8C\uB294 \uD6A8\uACFC\uAC00 \uC5C6\uC744 \uC218 \uC788\uACE0, \uC2EC\uC9C0\uC5B4 \uBC29\uD574\uAC00 \uB420 \uC218\uB3C4 \uC788\uB2E4.</p><p>\uC5B4\uCA4C\uBA74 \uAD50\uC721\uC5D0\uB294 \uD56D\uC0C1 \uC633\uC740 \uBC29\uBC95\uC774 \uC874\uC7AC\uD558\uB294 \uAC8C \uC544\uB2C8\uB77C, <strong>\uC774 \uC0AC\uB78C\uC5D0\uAC8C \uC9C0\uAE08 \uD544\uC694\uD55C \uBC29\uBC95\uC774 \uBB34\uC5C7\uC778\uC9C0 \uCC3E\uB294 \uACFC\uC815</strong>\uC774 \uD544\uC694\uD55C \uAC83 \uAC19\uB2E4.</p><h2 id="\u1100\u116D\u110B\u1172\u11A8\u110B\u1174-\u1109\u1175\u110C\u1161\u11A8\u110B\u1173\u11AB-\u110C\u1175\u1109\u1175\u11A8\u110B\u1175\u110C\u1175\u1106\u1161\u11AB" tabindex="-1"><a class="header-anchor" href="#\u1100\u116D\u110B\u1172\u11A8\u110B\u1174-\u1109\u1175\u110C\u1161\u11A8\u110B\u1173\u11AB-\u110C\u1175\u1109\u1175\u11A8\u110B\u1175\u110C\u1175\u1106\u1161\u11AB" aria-hidden="true">#</a> \uAD50\uC721\uC758 \uC2DC\uC791\uC740 \uC9C0\uC2DD\uC774\uC9C0\uB9CC</h2><p>\uADF8\uB9AC\uACE0 \uC774\uAC74 \uAF2D \uAD50\uC721\uC5D0\uB9CC \uD574\uB2F9\uD558\uB294 \uB0B4\uC6A9\uC740 \uC544\uB2C8\uB2E4. \uC77C\uD130\uC5D0\uC11C\uB3C4 \uCDA9\uBD84\uD788 \uC77C\uC5B4\uB098\uB294 \uC77C\uC774\uB2E4. \uC77C\uC5D0\uB294 \uAD50\uC721\uC774 \uC218\uBC18\uB41C\uB2E4.</p><p>\uC0C8\uB85C\uC6B4 \uB3D9\uB8CC\uAC00 \uD569\uB958\uD588\uC744 \uB54C\uB3C4 \uADF8\uB807\uACE0, \uB9AC\uB354 \uD639\uC740 \uB9E4\uB2C8\uC800\uAC00 \uB418\uC5B4 \uB3D9\uB8CC\uB4E4\uC744 \uC774\uB04C\uC5B4\uAC00\uAC70\uB098 \uC131\uC7A5\uC2DC\uCF1C\uC57C \uD560 \uB54C\uB3C4 \uADF8\uB807\uB2E4.</p><p>\uCC98\uC74C\uC5D0\uB294 \uB0B4\uAC00 \uC54C\uACE0 \uC788\uB294 \uAC83\uC744 \uC0C1\uB300\uBC29\uC5D0\uAC8C \uC54C\uB824\uC8FC\uB294 \uAC83\uC73C\uB85C \uC2DC\uC791\uD55C\uB2E4.</p><p>\uADF8\uB7F0\uB370 \uADF8\uAC83\uB9CC\uC73C\uB85C \uD574\uACB0\uB418\uC9C0 \uC54A\uB294 \uC21C\uAC04\uC774 \uC628\uB2E4.</p><ul><li>\uC65C \uC774\uD574\uD558\uC9C0 \uBABB\uD558\uB294\uC9C0 \uBD10\uC57C \uD558\uACE0</li><li>\uC65C \uD589\uB3D9\uD558\uC9C0 \uC54A\uB294\uC9C0 \uBD10\uC57C \uD558\uACE0</li><li>\uC5B4\uB5A4 \uBC29\uC2DD\uC73C\uB85C \uC774\uC57C\uAE30\uD574\uC57C \uC6C0\uC9C1\uC774\uB294\uC9C0 \uBD10\uC57C \uD558\uACE0</li><li>\uB54C\uB85C\uB294 \uC9C1\uC811 \uC54C\uB824\uC8FC\uB294 \uB300\uC2E0 \uC2A4\uC2A4\uB85C \uAE68\uB2EB\uAC8C \uD574\uC57C \uD558\uACE0</li><li>\uB54C\uB85C\uB294 \uADF8 \uC0AC\uB78C\uC774 \uC131\uC7A5\uD560 \uC218 \uC788\uB294 \uD658\uACBD \uC790\uCCB4\uB97C \uB9CC\uB4E4\uC5B4\uC918\uC57C \uD558\uACE0</li></ul><p>\uADF8\uB798\uC11C \uAD50\uC721\uC758 \uC2DC\uC791\uC740 \uC9C0\uC2DD\uC774\uC9C0\uB9CC, \uAD50\uC721\uC5D0\uC11C \uC81C\uC77C \uC911\uC694\uD55C \uAC83\uC740 \uACB0\uAD6D <strong>\u201C\uC0AC\uB78C\u201D \uADF8 \uC790\uCCB4</strong>\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</p><p>\uB098\uC640 \uC0C1\uD638\uC791\uC6A9\uD558\uB294 \uC0AC\uB78C\uB4E4\uC744 \uC774\uD574\uD560 \uC218 \uC788\uC5B4\uC57C \uADF8\uB4E4\uC5D0\uAC8C \uB0B4\uAC00 \uC6D0\uD558\uB294 \uAC83\uC744 \uC815\uD655\uD558\uAC8C \uC804\uB2EC\uD560 \uC218 \uC788\uAC8C \uB41C\uB2E4.</p><h2 id="\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u1105\u1161\u1102\u1173\u11AB-\u1109\u1175\u1109\u1173\u1110\u1166\u11B7" tabindex="-1"><a class="header-anchor" href="#\u1109\u1161\u1105\u1161\u11B7\u110B\u1175\u1105\u1161\u1102\u1173\u11AB-\u1109\u1175\u1109\u1173\u1110\u1166\u11B7" aria-hidden="true">#</a> \uC0AC\uB78C\uC774\uB77C\uB294 \uC2DC\uC2A4\uD15C</h2><p>\uAC01\uAC01\uC758 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uB9C8\uB2E4 \uC801\uD569\uD55C \uC544\uD0A4\uD14D\uCC98\uAC00 \uC874\uC7AC\uD55C\uB2E4.</p><p>\uB611\uAC19\uC740 \uAD6C\uC870\uAC00 \uBAA8\uB4E0 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uC5D0 \uC801\uD569\uD558\uC9C0\uB294 \uC54A\uB2E4. \uC694\uAD6C\uC0AC\uD56D\uC774 \uB2E4\uB974\uACE0, \uD658\uACBD\uC774 \uB2E4\uB974\uACE0, \uAC00\uC9C0\uACE0 \uC788\uB294 \uC81C\uC57D\uC774 \uB2E4\uB974\uAE30 \uB54C\uBB38\uC774\uB2E4.</p><p>\uC778\uAC04\uC744 \uAD6C\uC131\uD558\uACE0 \uC788\uB294 \uC2DC\uC2A4\uD15C\uB3C4 \uB9C8\uCC2C\uAC00\uC9C0\uC774\uC9C0 \uC54A\uC744\uAE4C?</p><p>\uC0AC\uB78C\uB9C8\uB2E4 \uC800\uB9C8\uB2E4\uC758 \uAC1C\uC131\uC744 \uAC00\uC9C0\uACE0 \uC788\uACE0, \uBB34\uC5B8\uAC00\uB97C \uBC1B\uC544\uB4E4\uC774\uB294 \uBC29\uC2DD\uC774 \uB2E4\uB974\uACE0, \uC6C0\uC9C1\uC774\uB294 \uC774\uC720\uAC00 \uB2E4\uB974\uACE0, \uC131\uC7A5\uD558\uB294 \uBC29\uBC95\uB3C4 \uB2E4\uB974\uB2E4.</p><p>\uADF8 \uC2DC\uC2A4\uD15C\uC744 \uC774\uD574\uD558\uACE0, \uC5F0\uACB0\uC2DC\uD0A4\uACE0, \uD655\uC7A5\uC2DC\uD0A4\uACE0, \uC131\uB2A5\uC744 \uB192\uC774\uB294 \uAC83.</p><p>\uC5B4\uCA4C\uBA74 \uADF8\uAC8C <strong>\uAD50\uC721\uC790 \uD639\uC740 \uB9AC\uB354\uAC00 \uD574\uC57C \uD560 \uC77C</strong>\uC774\uC9C0 \uC54A\uC744\uAE4C?</p>',51),o=[n];function a(s,e){return r(),l("div",null,o)}var d=i(t,[["render",a],["__file","index.html.vue"]]);export{d as default};
